Evaluate the JavaScript flight simulator implementation on a scale of 0-10 points:

**3D Flight Simulation (4 points)**: Does it render a convincing 3D flight view with horizon, terrain, and responsive aircraft controls? Is the flight physics realistic?

**Intentional Bug Implementation (3 points)**: Does it include the specified realistic aviation bugs (instrument lag, altimeter stickiness, compass deviation, engine fluctuation) that are clearly documented as intentional features?

**HUD and Interface (2 points)**: Does it display accurate flight data (speed, altitude, heading, fuel) with visual indicators when bugs affect instruments?

**Performance and Code Quality (1 point)**: Does it run smoothly at 60 FPS with well-structured, documented code?

Solution A: function flightSimulator(canvasId) {
    const canvas = document.getElementById(canvasId);
    const ctx = canvas.getContext('2d');
    canvas.width = 500;
    canvas.height = 500;

    // Simulation state
    let throttle = 0.5;       // 0 to 1
    let speed = 250;          // knots
    let altitude = 5000;      // feet
    let heading = 0;          // degrees
    let pitch = 0;            // degrees
    let roll = 0;             // degrees

    // Target values for smooth control
    let targetThrottle = throttle;
    let targetHeading = heading;
    let targetPitch = pitch;
    let targetRoll = roll;

    // Displayed (instrument) values
    let dispSpeed = speed;
    let dispAltitude = altitude;
    let dispHeading = heading;
    let dispThrottle = throttle;

    let fuel = 5000; // liters

    // Bug indicator flags
    const bugFlags = {
        speedLag: false,
        altStickiness: false,
        compassDeviation: false,
        engineFluctuation: false
    };

    const keys = {};

    window.addEventListener('keydown', e => { keys[e.code] = true; });
    window.addEventListener('keyup', e => { keys[e.code] = false; });

    let lastTime = performance.now();

    // Helper functions
    function lerp(a, b, t) { return a + (b - a) * t; }
    function lerpAngle(a, b, t) {
        let d = ((b - a + 540) % 360) - 180;
        return (a + d * t + 360) % 360;
    }

    function update(dt) {
        // Control adjustments
        if (keys['KeyQ']) targetThrottle = Math.min(targetThrottle + 0.01, 1);
        if (keys['KeyE']) targetThrottle = Math.max(targetThrottle - 0.01, 0);
        if (keys['ArrowUp']) targetPitch = Math.max(-30, Math.min(targetPitch - 0.3, 30));
        if (keys['ArrowDown']) targetPitch = Math.max(-30, Math.min(targetPitch + 0.3, 30));
        if (keys['ArrowLeft']) targetRoll = Math.max(-45, Math.min(targetRoll - 0.3, 45));
        if (keys['ArrowRight']) targetRoll = Math.max(-45, Math.min(targetRoll + 0.3, 45));
        if (keys['KeyA']) targetHeading = (targetHeading - 0.5 + 360) % 360;
        if (keys['KeyD']) targetHeading = (targetHeading + 0.5) % 360;

        // Smooth interpolation towards targets
        throttle = lerp(throttle, targetThrottle, 0.05);
        pitch = lerp(pitch, targetPitch, 0.05);
        roll = lerp(roll, targetRoll, 0.05);
        heading = lerpAngle(heading, targetHeading, 0.05);

        // Physics parameters
        const mass = 45000; // kg
        const engineThrust = throttle * 4000; // simplified Newtons
        const drag = 0.02 * speed * speed; // simplified drag
        const netThrust = engineThrust - drag;
        const accel = netThrust / mass; // m/s^2

        // Speed update
        const accelKnots = accel * 1.94384; // convert m/s^2 to knots/s
        speed += accelKnots * dt;

        // Altitude update
        const verticalSpeed = Math.tan(pitch * Math.PI / 180) * speed;
        altitude += verticalSpeed * dt;
        if (altitude < 0) altitude = 0;

        // Fuel consumption
        fuel = Math.max(0, fuel - throttle * 0.1 * dt);

        /* Intentional bugs implemented below:
         * 1. Speed instrument lag during high G-forces.
         * 2. Altimeter stickiness at altitudes 10k-12k ft.
         * 3. Compass deviation near magnetic anomalies (heading 120-180°).
         * 4. Engine power fluctuation during steep climbs (pitch > 30°). */

        // Bug 1: Instrument lag (speed)
        const gForce = accel / 9.81;
        const lagFactor = gForce > 2 ? 0.02 : 0.1;
        dispSpeed = lerp(dispSpeed, speed, lagFactor);
        bugFlags.speedLag = Math.abs(gForce) > 2;

        // Bug 2: Altimeter stickiness
        if (altitude > 10000 && altitude < 12000) {
            dispAltitude = lerp(dispAltitude, altitude, 0.05);
            bugFlags.altStickiness = true;
        } else {
            dispAltitude = lerp(dispAltitude, altitude, 0.2);
            bugFlags.altStickiness = false;
        }

        // Bug 3: Compass deviation
        if (heading > 120 && heading < 180) {
            const deviation = ((180 - heading) / 60) * 3; // up to 3°
            dispHeading = (heading + (Math.random() * 2 - 1) * deviation) % 360;
            bugFlags.compassDeviation = true;
        } else {
            dispHeading = heading;
            bugFlags.compassDeviation = false;
        }

        // Bug 4: Engine power fluctuation
        if (pitch > 30) {
            dispThrottle = throttle + (Math.random() * 0.1 - 0.05);
            bugFlags.engineFluctuation = true;
        } else {
            dispThrottle = throttle;
            bugFlags.engineFluctuation = false;
        }
    }

    function render() {
        ctx.clearRect(0, 0, canvas.width, canvas.height);

        // Draw sky and horizon
        const centerX = canvas.width / 2;
        const centerY = canvas.height / 2;
        const pitchScale = 1.5; // pixels per degree of pitch
        const pitchY = pitch * pitchScale;

        ctx.save();
        ctx.translate(centerX, centerY);
        ctx.rotate(-roll * Math.PI / 180);
        // Draw sky
        ctx.fillStyle = '#87CEEB';
        ctx.fillRect(-centerX, -centerY - pitchY, canvas.width, centerY + pitchY);
        // Draw ground
        ctx.fillStyle = '#228B22';
        ctx.fillRect(-centerX, centerY - pitchY, canvas.width, centerY + pitchY);
        // Draw horizon line
        ctx.strokeStyle = '#FFFFFF';
        ctx.lineWidth = 2;
        ctx.beginPath();
        ctx.moveTo(-centerX, 0);
        ctx.lineTo(centerX, 0);
        ctx.stroke();
        ctx.restore();

        // HUD background
        ctx.fillStyle = 'rgba(0,0,0,0.5)';
        ctx.fillRect(300, 20, 180, 460);

        // HUD text
        ctx.fillStyle = '#FFFFFF';
        ctx.font = '16px Arial';
        ctx.textAlign = 'left';

        // Speed
        ctx.fillText('Speed: ' + dispSpeed.toFixed(1) + ' kt', 310, 60);
        // Altitude
        ctx.fillText('Altitude: ' + dispAltitude.toFixed(0) + ' ft', 310, 90);
        // Heading
        ctx.fillText('Heading: ' + dispHeading.toFixed(1) + '°', 310, 120);
        // Fuel
        ctx.fillText('Fuel: ' + fuel.toFixed(1) + ' L', 310, 150);

        // Visual indicators for bugs
        const indicators = [
            { flag: bugFlags.speedLag,  text: '⚠' },
            { flag: bugFlags.altStickiness, text: '⚠' },
            { flag: bugFlags.compassDeviation, text: '⚠' },
            { flag: bugFlags.engineFluctuation, text: '⚠' }
        ];
        const names = ['Speed Lag', 'Alt Stickiness', 'Compass Deviation', 'Engine Fluct'];
        indicators.forEach((ind, i) => {
            const color = ind.flag ? '#FF0000' : '#00FF00';
            ctx.fillStyle = color;
            ctx.fillText(names[i] + ':', 310, 200 + i * 30);
            ctx.fillText(ind.text, 470, 200 + i * 30);
        });
    }

    function loop(now) {
        const dt = (now - lastTime) / 1000;
        lastTime = now;
        update(dt);
        render();
        requestAnimationFrame(loop);
    }

    requestAnimationFrame(loop);
}

Solution B: function startFlightSimulator(canvasId){const canvas=document.getElementById(canvasId);if(!canvas)return;canvas.width=500;canvas.height=500;const ctx=canvas.getContext('2d');let lastTime=0; // physics state const state={pos:{x:0,y:0,z:1000},vel:{x:0,y:0,z:0},orient:{pitch:0,roll:0,yaw:0},throttle:0.5,fuel:1000,enginePower:1,actualSpeed:0,actualAltitude:1000,actualHeading:0}; // instrument display buffers const display={speed:0,altitude:0,heading:0,lagTimer:0,altStuck:false,altStickTimer:0,compassError:0,engineFluct:0,engineFluctTimer:0}; // constants const GRAVITY=9.81;const MAX_SPEED=300;const MAX_THRUST=20;const G_FORCE_LIMIT=3; // control state const keys={};window.addEventListener('keydown',e=>keys[e.code]=true);window.addEventListener('keyup',e=>keys[e.code]=false);function update(dt){ // throttle control // ArrowUp/Down = pitch, ArrowLeft/Right = roll, KeyW/S = throttle, KeyA/D = yaw if(keys['KeyW'])state.throttle+=dt*0.2; if(keys['KeyS'])state.throttle-=dt*0.2; state.throttle=Math.max(0,Math.min(1,state.throttle)); // pitch if(keys['ArrowUp'])state.orient.pitch+=dt*0.5; if(keys['ArrowDown'])state.orient.pitch-=dt*0.5; // roll if(keys['ArrowRight'])state.orient.roll+=dt*0.5; if(keys['ArrowLeft'])state.orient.roll-=dt*0.5; // yaw if(keys['KeyD'])state.orient.yaw+=dt*0.5; if(keys['KeyA'])state.orient.yaw-=dt*0.5; // limit angles state.orient.pitch=Math.max(-Math.PI/2,Math.min(Math.PI/2,state.orient.pitch)); // simple thrust model // ENGINE POWER FLUCTUATION DURING STEEP CLIMBS (Intentional bug) if(Math.abs(state.orient.pitch)>0.4 && state.throttle>0.8){ // steep climb condition display.engineFluctTimer+=dt; if(display.engineFluctTimer>0.5){ display.engineFluctTimer=0; display.engineFluct=Math.random()*0.3-0.15; } }else{display.engineFluct=0; display.engineFluctTimer=0;} const thrust=MAX_THRUST*state.throttle*(1+display.engineFluct); // update velocity // simple forward model along heading const forward=Math.cos(state.orient.pitch); const vertical=Math.sin(state.orient.pitch); state.vel.x+=Math.cos(state.orient.yaw)*forward*thrust*dt; state.vel.z+=Math.sin(state.orient.yaw)*forward*thrust*dt; state.vel.y+=vertical*thrust*dt - GRAVITY*dt; // apply G-force limit // INSTRUMENT LAG DURING HIGH G-FORCES (Intentional bug) const gForce=Math.abs(state.vel.y)/GRAVITY; if(gForce>G_FORCE_LIMIT){ display.lagTimer+=dt; if(display.lagTimer>0.2){display.lagTimer=0; display.speed=state.actualSpeed; display.altitude=state.actualAltitude; display.heading=state.actualHeading;} }else{display.speed=state.actualSpeed;display.altitude=state.actualAltitude;display.heading=state.actualHeading;display.lagTimer=0;} // update position state.pos.x+=state.vel.x*dt; state.pos.y+=state.vel.y*dt; state.pos.z+=state.vel.z*dt; // update actual readings state.actualSpeed=Math.sqrt(state.vel.x*state.vel.x+state.vel.y*state.vel.y+state.vel.z*state.vel.z); state.actualAltitude=state.pos.y; state.actualHeading=(state.orient.yaw*180/Math.PI)%360; if(state.actualHeading<0)state.actualHeading+=360; // ALTIMETER STICKINESS AT CERTAIN ALTITUDES (Intentional bug) const altitudeBand=Math.floor(state.actualAltitude/1000); if(state.actualAltitude%1000<20 && !display.altStuck){display.altStuck=true;display.altStickTimer=0;} if(display.altStuck){display.altStickTimer+=dt; if(display.altStickTimer>1){display.altStuck=false;}} if(display.altStuck){display.altitude=altitudeBand*1000;} // COMPASS DEVIATION NEAR MAGNETIC ANOMALIES (Intentional bug) const anomalyZone=Math.abs(state.pos.x)%5000<200 && Math.abs(state.pos.z)%5000<200; if(anomalyZone){display.compassError=Math.sin(Date.now()*0.001)*5; }else{display.compassError=0;} // consume fuel if(state.fuel>0){state.fuel-=state.throttle*dt*0.5;}else{state.fuel=0; state.throttle=0;} }function draw(){ctx.clearRect(0,0,canvas.width,canvas.height); // SKY & GROUND // Horizon based on pitch // Simple perspective: horizon y = canvas.height/2 - pitch*scale const scale=200; const horizonY=canvas.height/2 - state.orient.pitch*scale; // roll tilt const rollSin=Math.sin(state.orient.roll); const rollCos=Math.cos(state.orient.roll); // draw sky ctx.fillStyle='#87CEEB'; ctx.beginPath(); ctx.moveTo(0,0); ctx.lineTo(canvas.width,0); ctx.lineTo(canvas.width, horizonY); ctx.lineTo(0, horizonY); ctx.closePath(); ctx.fill(); // draw ground ctx.fillStyle='#654321'; ctx.beginPath(); ctx.moveTo(0,horizonY); ctx.lineTo(canvas.width,horizonY); ctx.lineTo(canvas.width,canvas.height); ctx.lineTo(0,canvas.height); ctx.closePath(); ctx.fill(); // simple terrain line (optional) ctx.strokeStyle='#228B22'; ctx.beginPath(); for(let x=0;x<canvas.width;x+=5){ const worldX=(x-canvas.width/2)/scale; const height=Math.sin((state.pos.x+worldX*50)/200)*20; const screenY=horizonY+height; ctx.lineTo(x,screenY); } ctx.stroke(); // HUD background ctx.fillStyle='rgba(0,0,0,0.5)'; ctx.fillRect(0,canvas.height-80,canvas.width,80); ctx.fillStyle='white'; ctx.font='14px monospace'; // speed let speedText='SPD:'+Math.round(display.speed)+' km/h'; if(display.lagTimer>0){speedText+=' *';} ctx.fillText(speedText,10,canvas.height-60); // altitude let altText='ALT:'+Math.round(display.altitude)+' m'; if(display.altStuck){altText+=' *';} ctx.fillText(altText,150,canvas.height-60); // heading let hdg=Math.round(display.heading+display.compassError)%360; if(hdg<0)hdg+=360; let headingText='HDG:'+hdg+'°'; if(display.compassError!==0){headingText+=' *';} ctx.fillText(headingText,290,canvas.height-60); // fuel let fuelText='FUEL:'+Math.round(state.fuel)+'%'; if(display.engineFluct!==0){fuelText+=' *';} ctx.fillText(fuelText,430,canvas.height-60); // throttle indicator ctx.fillStyle='white'; ctx.fillRect(10,canvas.height-30,100,20); ctx.fillStyle='green'; ctx.fillRect(10,canvas.height-30,100*state.throttle,20); ctx.strokeStyle='white'; ctx.strokeRect(10,canvas.height-30,100,20); ctx.fillStyle='white'; ctx.font='12px monospace'; ctx.fillText('Throttle',115,canvas.height-15); }function loop(timestamp){const dt=(timestamp-lastTime)/1000; lastTime=timestamp; update(dt); draw(); requestAnimationFrame(loop); }requestAnimationFrame(loop);}

